/** Builds the shared predicate list behind `listIssues` and its count. */
function issueFilters(input: IssueFilterInput): readonly SQL[] {
  const scope: ArchiveScope = shouldFilterArchived({
    includeArchived: input.includeArchived === true || input.includeArchived === "only",
  })
    ? {}
    : { includeArchived: true };

  return compact(
    orgPredicate(issues.orgId, input.orgId),
    input.includeArchived === "only"
      ? isNotNull(issues.archivedAt)
      : livePredicate(issues.archivedAt, scope),
    input.projectId === undefined
      ? undefined
      : eq(issues.projectId, input.projectId),
    input.status === undefined || input.status.length === 0
      ? undefined
      : inArray(issues.status, expandIssueStatuses(input.status)),
    input.priority === undefined || input.priority.length === 0
      ? undefined
      : inArray(issues.priority, [...input.priority]),
    input.assigneeId === undefined ? undefined : input.assigneeId === null
      ? isNull(issues.assigneeId) : eq(issues.assigneeId, input.assigneeId),
    input.authorId === undefined
      ? undefined
      : eq(issues.authorId, input.authorId),
    input.dueBefore === undefined ? undefined
      : /^\d{4}-\d{2}-\d{2}$/.test(input.dueBefore)
        ? sql`julianday(${issues.dueAt}) < julianday(${input.dueBefore}) + 1`
        : sql`julianday(${issues.dueAt}) < julianday(${input.dueBefore})`,
    input.query === undefined
      ? undefined
      : or(
          like(issues.title, `%${input.query}%`),
          like(issues.description, `%${input.query}%`),
        ),
    input.labelIds === undefined || input.labelIds.length === 0
      ? undefined
      : inArray(
          issues.id,
          getDb()
            .select({ id: issueLabels.issueId })
            .from(issueLabels)
            .where(
              and(
                orgPredicate(issueLabels.orgId, input.orgId),
                inArray(issueLabels.labelId, [...input.labelIds]),
              ),
            )
            .groupBy(issueLabels.issueId)
            .having(sql`count(distinct ${issueLabels.labelId}) = ${new Set(input.labelIds).size}`),
        ),
  );
}

